def try_family(I,O,fam):
    ok=True
    for desc,(a,b,c,d,prio) in fam:
        pred=[[0]*len(O[0]) for _ in O]
        # prio: None -> any nonzero wins; 'a' prefer left block, 'b' prefer right
        for rr in range(len(O)):
            for cc in range(len(O[0])):
                cand=[]
                for r_ in range(len(I)):
                    for c_ in range(len(I[0])):
                        if I[r_][c_]!=0:
                            rr_,cc_=a*r_+b,c_*d+c
                            if 0<=rr_<len(O) and 0<=cc_<len(O[0]):
                                cand.append((I[r_][c_],rr_,cc_))
                if cand:
                    best=max(cand,key=lambda x:(x[0]!=0))
                    pred[rr_][cc_]=best[0]
                elif prio=='a': pred[rr_][cc_]=None  # marker
        # compare: ignore cells where pred has no candidate? just check equality where pred nonzero
        mism=[(rr,cc,pred[rr][cc],O[rr][cc]) for rr in range(len(O)) for cc in range(len(O[0]))
               if pred[rr][cc]!=O[rr][cc]]
        if not mism: break
        ok=False
    return ok,desc
